sitemapindex:
{%- comment -%}
  Read custom sitemap URLs from _data/sitemaps.yml (safe fallback if file is missing or empty).
{%- endcomment -%}
{%- assign yml_sitemaps = site.data.sitemaps -%}
{%- if yml_sitemaps -%}
  {%- for item in yml_sitemaps -%}
    {%- assign url_loc = nil -%}
    {%- assign lastmod = nil -%}

    {%- if item.url or item.loc -%}
      {%- assign url_loc = item.url | default: item.loc -%}
      {%- assign lastmod = item.lastmod | default: item.last_modified_at | default: item.date -%}
    {%- else -%}
      {%- assign url_loc = item -%}
    {%- endif -%}

    {%- if url_loc -%}

        {{ url_loc | absolute_url }}
        {%- if lastmod -%}
        {{ lastmod | date_to_xmlschema }}
        {%- endif -%}

    {%- endif -%}
  {%- endfor -%}
{%- endif -%}
